mapper.select:
select a.*, a.id as violationId, u.name as userName, v.plate as violationPlate, v.status as violationStatus from appealed a left join violation v on a.id = v.id left join user u on v.ownerid = u.id_card
and a.id = #{violationId}
and u.name like concat('%', #{userName}, '%')
and v.status = #{violationStatus}
order by a.id desc
